INSERT INTO categories (slug, name, heading, intro, image, banner, seo_title, seo_desc, in_menu, sort_order) VALUES ('chains', 'Chains', 'Chains', 'Handcrafted chains in gold and silver — kite, curb, barrel and two-tone links, made to be worn every day.', 'assets/images/campaign/cat-chains.jpg', 'assets/images/campaign/banner-chains.jpg', 'Gold & Silver Chains — Mangalam Jewellers', 'Handcrafted gold and silver chains from Mangalam Jewellers, Surat — kite, curb, engraved barrel and two-tone links.', 1, 7) ON DUPLICATE KEY UPDATE name = VALUES(name), heading = VALUES(heading), intro = VALUES(intro), image = VALUES(image), banner = VALUES(banner), seo_title = VALUES(seo_title), seo_desc = VALUES(seo_desc), in_menu = VALUES(in_menu), sort_order = VALUES(sort_order);
INSERT INTO categories (slug, name, heading, intro, image, banner, seo_title, seo_desc, in_menu, sort_order) VALUES ('watches', 'Watches', 'Watches', 'Watches finished in our atelier — a Victoria silver coin dial or a black dial on handcrafted gold. Jewellery that keeps time.', 'assets/images/campaign/cat-watches.jpg', 'assets/images/campaign/banner-watches.jpg', 'Watches — Mangalam Jewellers', 'Watches from Mangalam Jewellers, Surat: a Victoria Empress 999 silver coin watch and a black-dial watch on a handcrafted gold bracelet.', 1, 8) ON DUPLICATE KEY UPDATE name = VALUES(name), heading = VALUES(heading), intro = VALUES(intro), image = VALUES(image), banner = VALUES(banner), seo_title = VALUES(seo_title), seo_desc = VALUES(seo_desc), in_menu = VALUES(in_menu), sort_order = VALUES(sort_order);
