INSERT INTO products (slug, name, category_id, price, metal, purity, stone, style, line, summary, details, image_position, is_new, show_price, allow_enquiry, status, seo_title, seo_desc, sort_order) SELECT 'peacock-kundan-kada-pair', 'Peacock Kundan Kada Pair', id, 0, 'Gold', '22K', 'Kundan', 'Bridal', 'Mangalam Signature', 'A pair of wide gold kadas with peacocks and flowers in rubies, emeralds and sapphire-blue stones, edged with seed pearls.', 'Granulated 22K gold kadas carry peacocks and blossoms picked out in red, green and blue stones, framed by rows of seed pearls. Part of the Rajwadi Antique Bridal Set, and sold on their own as a pair. Every gold piece carries a BIS hallmark.', 'center', 1, 0, 1, 'published', '', 'A pair of wide gold kadas with peacocks and flowers in rubies, emeralds and sapphire-blue stones, edged with seed pearls.', 28 FROM categories WHERE slug = 'bangles' ON DUPLICATE KEY UPDATE name = VALUES(name), category_id = VALUES(category_id), metal = VALUES(metal), purity = VALUES(purity), stone = VALUES(stone), style = VALUES(style), line = VALUES(line), summary = VALUES(summary), details = VALUES(details), seo_desc = VALUES(seo_desc), sort_order = VALUES(sort_order);
