INSERT INTO products (slug, name, category_id, price, metal, purity, stone, style, line, summary, details, image_position, is_new, show_price, allow_enquiry, status, seo_title, seo_desc, sort_order) SELECT 'black-dial-gold-bracelet-watch', 'Black Dial Gold Bracelet Watch', id, 0, 'Gold', '22K', 'None', 'Classic', 'Mangalam Signature', 'A slim black-dial watch on a handcrafted gold bracelet with pavé-set links.', 'A minimal black dial with gold hands, on a bracelet of faceted gold links set with pavé lozenges and a pavé clasp. Every gold piece carries a BIS hallmark.', 'center', 1, 0, 1, 'published', '', 'A slim black-dial watch on a handcrafted gold bracelet with pavé-set links.', 41 FROM categories WHERE slug = 'watches' ON DUPLICATE KEY UPDATE name = VALUES(name), category_id = VALUES(category_id), metal = VALUES(metal), purity = VALUES(purity), stone = VALUES(stone), style = VALUES(style), line = VALUES(line), summary = VALUES(summary), details = VALUES(details), seo_desc = VALUES(seo_desc), sort_order = VALUES(sort_order);
