INSERT INTO products (slug, name, category_id, price, metal, purity, stone, style, line, summary, details, image_position, is_new, show_price, allow_enquiry, status, seo_title, seo_desc, sort_order) SELECT 'rajwadi-antique-bridal-set', 'Rajwadi Antique Bridal Set', id, 0, 'Gold', '22K', 'Kundan', 'Bridal', 'The Bridal Edit', 'A Rajwadi bridal set in antique gold: a layered necklace with a kundan medallion, temple jhumkas and peacock kadas.', 'The necklace builds layer upon layer of gold beads and kundan motifs to a central medallion of rubies and enamel, finished with a filigree drop. With it come tiered temple jhumkas and the Peacock Kundan Kada Pair, all in antique-finish 22K gold. Every gold piece carries a BIS hallmark.', 'center', 1, 0, 1, 'published', '', 'A Rajwadi bridal set in antique gold: a layered necklace with a kundan medallion, temple jhumkas and peacock kadas.', 42 FROM categories WHERE slug = 'bridal' ON DUPLICATE KEY UPDATE name = VALUES(name), category_id = VALUES(category_id), metal = VALUES(metal), purity = VALUES(purity), stone = VALUES(stone), style = VALUES(style), line = VALUES(line), summary = VALUES(summary), details = VALUES(details), seo_desc = VALUES(seo_desc), sort_order = VALUES(sort_order);
INSERT INTO product_images (product_id, path, sort_order) SELECT p.id, x.path, x.n FROM products p JOIN (SELECT 'assets/images/products/bridal-rajwadi-set.jpg' AS path, 1 AS n UNION ALL SELECT 'assets/images/products/bridal-rajwadi-set-2.jpg' AS path, 2 AS n UNION ALL SELECT 'assets/images/products/bridal-rajwadi-set-3.jpg' AS path, 3 AS n) x WHERE p.slug = 'rajwadi-antique-bridal-set';
INSERT INTO product_images (product_id, path, sort_order) SELECT p.id, x.path, x.n FROM products p JOIN (SELECT 'assets/images/products/earring-chandelier.jpg' AS path, 1 AS n UNION ALL SELECT 'assets/images/products/earring-chandelier-2.jpg' AS path, 2 AS n) x WHERE p.slug = 'maharani-bridal-chandeliers';
