INSERT INTO products (slug, name, category_id, price, metal, purity, stone, style, line, summary, details, image_position, is_new, show_price, allow_enquiry, status, seo_title, seo_desc, sort_order) SELECT 'saat-phere-bridal-set', 'Saat Phere Bridal Set', id, 0, 'Gold', '22K', 'Polki', 'Bridal', 'The Bridal Edit', 'A complete bridal look: polki necklace, maang tikka, earrings, rings and bangles composed together.', 'Composed for the pheras — a polki necklace, maang tikka, earrings, statement rings and bangles in 22K gold, designed to be worn together. Each piece can be ordered on its own. Every gold piece carries a BIS hallmark.', 'center', 1, 0, 1, 'published', '', 'A complete bridal look: polki necklace, maang tikka, earrings, rings and bangles composed together.', 45 FROM categories WHERE slug = 'bridal' ON DUPLICATE KEY UPDATE name = VALUES(name), category_id = VALUES(category_id), metal = VALUES(metal), purity = VALUES(purity), stone = VALUES(stone), style = VALUES(style), line = VALUES(line), summary = VALUES(summary), details = VALUES(details), seo_desc = VALUES(seo_desc), sort_order = VALUES(sort_order);
