INSERT INTO products (slug, name, category_id, price, metal, purity, stone, style, line, summary, details, image_position, is_new, show_price, allow_enquiry, status, seo_title, seo_desc, sort_order) SELECT 'gujarati-rani-haar', 'Gujarati Rani Haar', id, 0, 'Gold', '22K', 'Kundan', 'Bridal', 'The Bridal Edit', 'A long rani haar of gold and kundan, ending in a round kundan medallion.', 'Layered gold work runs the full length of this long haar to a round medallion of kundan, rubies and emeralds. A Gujarati heirloom design for the bride. Every gold piece carries a BIS hallmark.', 'center', 1, 0, 1, 'published', '', 'A long rani haar of gold and kundan, ending in a round kundan medallion.', 47 FROM categories WHERE slug = 'bridal' ON DUPLICATE KEY UPDATE name = VALUES(name), category_id = VALUES(category_id), metal = VALUES(metal), purity = VALUES(purity), stone = VALUES(stone), style = VALUES(style), line = VALUES(line), summary = VALUES(summary), details = VALUES(details), seo_desc = VALUES(seo_desc), sort_order = VALUES(sort_order);
