INSERT INTO products (slug, name, category_id, price, metal, purity, stone, style, line, summary, details, image_position, is_new, show_price, allow_enquiry, status, seo_title, seo_desc, sort_order) SELECT 'bridal-maang-tikka', 'Bridal Maang Tikka', id, 0, 'Gold', '22K', 'Kundan', 'Bridal', 'The Bridal Edit', 'A kundan maang tikka finished with green bead drops.', 'A kundan tikka in 22K gold on a fine chain, ending in a fringe of green beads and gold. Every gold piece carries a BIS hallmark.', 'center', 1, 0, 1, 'published', '', 'A kundan maang tikka finished with green bead drops.', 48 FROM categories WHERE slug = 'bridal' ON DUPLICATE KEY UPDATE name = VALUES(name), category_id = VALUES(category_id), metal = VALUES(metal), purity = VALUES(purity), stone = VALUES(stone), style = VALUES(style), line = VALUES(line), summary = VALUES(summary), details = VALUES(details), seo_desc = VALUES(seo_desc), sort_order = VALUES(sort_order);
