INSERT INTO products (slug, name, category_id, price, metal, purity, stone, style, line, summary, details, image_position, is_new, show_price, allow_enquiry, status, seo_title, seo_desc, sort_order) SELECT 'royal-bridal-nath', 'Royal Bridal Nath', id, 0, 'Gold', '22K', 'Pearl', 'Bridal', 'The Bridal Edit', 'A bridal nath of gold, pearls and coloured beads.', 'A traditional bridal nose ring in 22K gold strung with pearls and red and green beads, with a chain to rest along the cheek. Every gold piece carries a BIS hallmark.', 'center', 1, 0, 1, 'published', '', 'A bridal nath of gold, pearls and coloured beads.', 49 FROM categories WHERE slug = 'bridal' ON DUPLICATE KEY UPDATE name = VALUES(name), category_id = VALUES(category_id), metal = VALUES(metal), purity = VALUES(purity), stone = VALUES(stone), style = VALUES(style), line = VALUES(line), summary = VALUES(summary), details = VALUES(details), seo_desc = VALUES(seo_desc), sort_order = VALUES(sort_order);
