-- Mangalam Jewellers — catalogue update, 8 October 2026
-- Every piece shows only its own photographs, with names, categories and details checked against the
-- product shoot. Adds the Chains and Watches categories (silver pieces are found by their metal) and the pieces from the shoot that were not
-- on the website. Upload assets/images/products/ and assets/images/campaign/ first, then run this file
-- (phpMyAdmin › Import, or: mysql database < this-file). Matched by slug; safe to run more than once.
-- Prices, weights, HUID, 3D settings, featured order, New labels and publish status of existing pieces
-- are not changed. New pieces show "Price on request" until a price is entered in the admin.

SET NAMES utf8mb4;
START TRANSACTION;

-- 1. Categories (new ones added; menu order)
UPDATE categories SET sort_order = 1 WHERE slug = 'rings';
UPDATE categories SET sort_order = 2 WHERE slug = 'necklaces';
UPDATE categories SET sort_order = 3 WHERE slug = 'earrings';
UPDATE categories SET sort_order = 4 WHERE slug = 'bangles';
UPDATE categories SET sort_order = 5 WHERE slug = 'bracelets';
UPDATE categories SET sort_order = 6 WHERE slug = 'pendants';
UPDATE categories SET sort_order = 9 WHERE slug = 'bridal';

-- Silver is a metal, shown under Shop by metal › Silver jewellery, not a category of its own
UPDATE products SET category_id = (SELECT id FROM categories WHERE slug = 'chains') WHERE slug = 'two-tone-silver-link-chain';
UPDATE products SET category_id = (SELECT id FROM categories WHERE slug = 'watches') WHERE slug = 'victoria-silver-coin-watch';
DELETE FROM categories WHERE slug = 'silver' AND NOT EXISTS (SELECT 1 FROM products p WHERE p.category_id = categories.id);
DELETE FROM media WHERE path IN ('assets/images/campaign/cat-silver.jpg', 'assets/images/campaign/banner-silver.jpg');

-- 2. Photographs renamed to match the piece
UPDATE media SET path = 'assets/images/products/necklace-pearl-choker.jpg', name = 'necklace-pearl-choker.jpg' WHERE path = 'assets/images/products/bracelet-pearl-kundan.jpg' AND NOT EXISTS (SELECT 1 FROM (SELECT path FROM media) m WHERE m.path = 'assets/images/products/necklace-pearl-choker.jpg');
DELETE FROM media WHERE path = 'assets/images/products/bracelet-pearl-kundan.jpg';
UPDATE media SET path = 'assets/images/products/necklace-pearl-choker-2.jpg', name = 'necklace-pearl-choker-2.jpg' WHERE path = 'assets/images/products/bracelet-pearl-kundan-2.jpg' AND NOT EXISTS (SELECT 1 FROM (SELECT path FROM media) m WHERE m.path = 'assets/images/products/necklace-pearl-choker-2.jpg');
DELETE FROM media WHERE path = 'assets/images/products/bracelet-pearl-kundan-2.jpg';
UPDATE media SET path = 'assets/images/products/necklace-sage-polki.jpg', name = 'necklace-sage-polki.jpg' WHERE path = 'assets/images/products/bridal-polki-set.jpg' AND NOT EXISTS (SELECT 1 FROM (SELECT path FROM media) m WHERE m.path = 'assets/images/products/necklace-sage-polki.jpg');
DELETE FROM media WHERE path = 'assets/images/products/bridal-polki-set.jpg';
UPDATE media SET path = 'assets/images/products/necklace-sage-polki-2.jpg', name = 'necklace-sage-polki-2.jpg' WHERE path = 'assets/images/products/bridal-polki-set-2.jpg' AND NOT EXISTS (SELECT 1 FROM (SELECT path FROM media) m WHERE m.path = 'assets/images/products/necklace-sage-polki-2.jpg');
DELETE FROM media WHERE path = 'assets/images/products/bridal-polki-set-2.jpg';

-- 3. Duplicates removed (their photographs belong to other pieces)
DELETE FROM products WHERE slug IN ('classic-gold-pendant', 'heritage-pendant');

-- 4. Every piece: name, category, metal, purity, stone, style, description; new pieces added
